+// first-layer temperature further than 30 °C from the other layers' on the
+// nozzle, or 15 °C on a plate, both above zero. OrcaSlicer lists every such
+// pair in one dialog; each comes back here as that dialog words it when the
+// pair is the only one, with the first-layer values it accepts as min and
+// max. `config` is the filament as it would be saved.
+inline void forward_save_questions(const DynamicPrintConfig& config, std::vector<SettingIssue>& warnings)
+{
+    struct Pair { wxString label; std::string first, other; int limit; };
+    std::vector<Pair> pairs{{_L("Nozzle"), "nozzle_temperature_initial_layer", "nozzle_temperature", 30}};
+    if (const ConfigOptionDef* beds = print_config_def.get("curr_bed_type"))
